[Resource from github at repo://missingbulb/EdFringeNow/sha/b1c2b129366d782a43cd156584dacfcd9ed50a47/contents/.claudinite/local/packs/edfringe/verify-sh-source-dirs.mjs] // Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const VERIFY = 'scripts/verify.sh';

// The `git ls-files 'js' 'plan' 'shared'` call in verify.sh's "JavaScript
// syntax" step — captures its quoted top-level-directory arguments.
const LS_FILES_DIRS = /git ls-files((?:\s+'[^']*')+)/;
const JS_FILE = /\.m?js$/;

const rule = {
  id: 'edfringe-verify-sh-covers-source-dirs',
  severity: 'blocking',
  description:
    'scripts/verify.sh\'s JavaScript syntax-check step names every top-level directory that has committed .js/.mjs source',
  why:
    'the step only walks the top-level directories named in its `git ls-files` call; a source directory left off that list is silently never parse-checked, in the pre-commit hook or in CI',
  doc: 'RULES.md',

  run(ctx) {
    const verifyRaw = ctx.read(VERIFY);
    if (verifyRaw === null) return []; // relevance-first: no gate script, nothing to check

    const m = LS_FILES_DIRS.exec(verifyRaw);
    const listed = new Set((m ? m[1].match(/'([^']*)'/g) : []).map((s) => s.slice(1, -1)));

    const present = new Set();
    for (const f of ctx.files) {
      if (!JS_FILE.test(f)) continue;
      const slash = f.indexOf('/');
      if (slash === -1) continue; // a bare top-level file, not inside a directory
      const top = f.slice(0, slash);
      if (top.startsWith('.')) continue; // hidden/tooling dirs (.claudinite, .github, ...) are out of scope
      present.add(top);
    }

    const missing = [...present].filter((d) => !listed.has(d)).sort();
    if (missing.length === 0) return [];

    const plural = missing.length > 1;
    return [finding(
      `${missing.join(', ')} ${plural ? 'have' : 'has'} committed .js/.mjs files but ${plural ? "aren't" : "isn't"} named in ${VERIFY}'s \`git ls-files\` syntax-check step`,
      `add ${missing.map((d) => `'${d}'`).join(' ')} to the \`git ls-files\` call in ${VERIFY} — or, if the directory is deliberately excluded (vendored/generated content), extend its grep -v filter instead`,
    )];
  },
};

function finding(what, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file: VERIFY,
    line: null,
    what,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

[Resource from github at repo://missingbulb/EdFringeNow/sha/b1c2b129366d782a43cd156584dacfcd9ed50a47/contents/.claudinite/local/packs/edfringe/no-stray-package-json.mjs] // Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

// The pinned Node 22 detects a .js file's module syntax on its own — no
// package.json needed to mark a directory as ESM. `plan/package.json` predates
// that detection and stays only as a grandfathered no-op; it must not become a
// pattern copied into every new source directory.
const ALLOWED = new Set(['package.json', 'plan/package.json']);

const rule = {
  id: 'edfringe-no-stray-package-json',
  severity: 'advisory',
  description: 'No package.json exists outside the repo root and the grandfathered plan/package.json',
  why:
    'a package.json is not needed to mark a directory as ESM — the pinned Node 22 detects module syntax in a .js file on its own — so a new one is very likely a copy of the plan/ leftover rather than something that does anything',
  doc: 'RULES.md',

  run(ctx) {
    const stray = ctx.files.filter((f) => f.endsWith('/package.json') && !ALLOWED.has(f)).sort();
    if (stray.length === 0) return [];

    return stray.map((f) => finding(f,
      `${f} is not needed to mark its directory as ESM (node --check and the test suite already detect module syntax unaided) — remove it, unless it genuinely configures its own dependencies/scripts`,
    ));
  },
};

function finding(file, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} is a package.json outside the repo root and plan/`,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

[Resource from github at repo://missingbulb/EdFringeNow/sha/b1c2b129366d782a43cd156584dacfcd9ed50a47/contents/.claudinite/local/packs/edfringe/test-globs-in-step.mjs] // Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.

const PKG = 'package.json';
const VERIFY = 'scripts/verify.sh';

// The `node --test <globs...>` invocation, wherever it appears in a shell script
// or a package.json script string. Anchored per line so verify.sh's prose
// comments above it can mention the command without matching.
const NODE_TEST = /^\s*node --test\s+(.+?)\s*$/m;

// If verify.sh delegates to the package script instead of repeating the globs,
// there is one source of truth and nothing to drift — the check stands down.
const DELEGATES = /\bnpm (?:run )?test\b/;

const rule = {
  id: 'edfringe-test-globs-in-step',
  severity: 'blocking',
  description:
    'The `node --test` file globs in package.json\'s "test" script and in scripts/verify.sh name the same set of test files',
  why:
    'CI and the pre-commit hook run scripts/verify.sh while a developer runs `npm test`, so the same list is spelled twice; a glob added to only one of them means a suite that is green locally and never runs in CI, or one that runs in CI and is invisible to whoever is editing it',
  doc: 'scripts/verify.sh',

  run(ctx) {
    const pkgRaw = ctx.read(PKG);
    const verifyRaw = ctx.read(VERIFY);
    // Relevance-first: a tree without both files has no duplication to guard.
    if (pkgRaw === null || verifyRaw === null) return [];

    let pkg;
    try {
      pkg = JSON.parse(pkgRaw);
    } catch {
      return []; // not this check's business — JSON validity is caught elsewhere
    }

    const script = pkg?.scripts?.test;
    if (typeof script !== 'string') return [];

    const pkgMatch = NODE_TEST.exec(script);
    const verifyMatch = NODE_TEST.exec(verifyRaw);

    // Neither side runs `node --test` from here: nothing is duplicated.
    if (!pkgMatch && !verifyMatch) return [];

    if (pkgMatch && !verifyMatch) {
      if (DELEGATES.test(verifyRaw)) return []; // single-sourced through `npm test`
      return [finding(
        `package.json's "test" script runs \`node --test\` but ${VERIFY} runs no unit tests at all`,
        `add the \`node --test\` line back to ${VERIFY}, or have it call \`npm test\` so the globs live in one place`,
      )];
    }
    if (verifyMatch && !pkgMatch) {
      return [finding(
        `${VERIFY} runs \`node --test\` but package.json's "test" script does not`,
        `point package.json's "test" script at the same globs, or at \`bash ${VERIFY}\``,
      )];
    }

    const inPkg = globs(pkgMatch[1]);
    const inVerify = globs(verifyMatch[1]);
    const onlyPkg = inPkg.filter((g) => !inVerify.includes(g));
    const onlyVerify = inVerify.filter((g) => !inPkg.includes(g));
    if (onlyPkg.length === 0 && onlyVerify.length === 0) return [];

    const parts = [];
    if (onlyPkg.length) parts.push(`only in package.json: ${onlyPkg.join(' ')}`);
    if (onlyVerify.length) parts.push(`only in ${VERIFY}: ${onlyVerify.join(' ')}`);
    return [finding(
      `the \`node --test\` globs have drifted apart — ${parts.join('; ')}`,
      `add the missing glob to both lines (they are meant to be identical), or have ${VERIFY} call \`npm test\` so there is only one list`,
    )];
  },
};

/** The whitespace-separated glob arguments, order-insensitive and de-duped. */
function globs(args) {
  return [...new Set(args.split(/\s+/).filter(Boolean))].sort();
}

function finding(what, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file: VERIFY,
    line: null,
    what,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

export default rule;

